triple_bond_molecules = set(row[0] for row in cursor.fetchall())
conn.close()
atom_counts = {}
with open('csv/atom.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        mol_id = row['molecule_id']
        element = row['element'].lower()
        if mol_id not in atom_counts:
            atom_counts[mol_id] = {'total': 0, 'elements': set()}
        atom_counts[mol_id]['total'] += 1
        atom_counts[mol_id]['elements'].add(element)
target_molecules = set()
for mol_id in triple_bond_molecules:
